-- Baseline schema for job-service.
--
-- Generated by scripts/gen-migration-baseline.sh from the schema the previous
-- GORM AutoMigrate path produced. Every statement is idempotent, so this
-- migration is a NO-OP on a database that already has the schema (existing
-- production) and creates it on a fresh one — which is why no stamping step is
-- needed to adopt migrations on a live database.
--
-- Do not edit by hand: change the models and regenerate, or add a NEW numbered
-- migration for schema changes from here on.

-- +goose Up
CREATE TABLE IF NOT EXISTS public.file_metadata (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    kind text NOT NULL,
    original_name text NOT NULL,
    path text NOT NULL,
    size_bytes bigint NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.processing_jobs (
    id uuid NOT NULL,
    user_id uuid,
    tool_type text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    progress bigint DEFAULT 0,
    file_name text NOT NULL,
    file_size bigint DEFAULT 0,
    failure_reason text,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone,
    CONSTRAINT chk_job_status CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'completed'::text, 'failed'::text])))
);

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'file_metadata_pkey'
                     AND conrelid = 'public.file_metadata'::regclass) THEN
        ALTER TABLE ONLY public.file_metadata
            ADD CONSTRAINT file_metadata_pkey PRIMARY KEY (id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'processing_jobs_pkey'
                     AND conrelid = 'public.processing_jobs'::regclass) THEN
        ALTER TABLE ONLY public.processing_jobs
            ADD CONSTRAINT processing_jobs_pkey PRIMARY KEY (id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

CREATE INDEX IF NOT EXISTS idx_file_metadata_job_id ON public.file_metadata USING btree (job_id);

CREATE INDEX IF NOT EXISTS idx_filemeta_job_kind ON public.file_metadata USING btree (job_id, kind);

CREATE INDEX IF NOT EXISTS idx_filemeta_path ON public.file_metadata USING btree (path);

CREATE INDEX IF NOT EXISTS idx_job_missing_expiry ON public.processing_jobs USING btree (id) WHERE ((expires_at IS NULL) AND (user_id IS NOT NULL));

CREATE INDEX IF NOT EXISTS idx_job_user_created ON public.processing_jobs USING btree (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_job_user_tool_created ON public.processing_jobs USING btree (user_id, tool_type, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_processing_jobs_expires_at ON public.processing_jobs USING btree (expires_at);

CREATE INDEX IF NOT EXISTS idx_processing_jobs_status ON public.processing_jobs USING btree (status);

CREATE INDEX IF NOT EXISTS idx_processing_jobs_tool_type ON public.processing_jobs USING btree (tool_type);

-- +goose StatementBegin
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'fk_file_metadata_processing_job'
                     AND conrelid = 'public.file_metadata'::regclass) THEN
        ALTER TABLE ONLY public.file_metadata
            ADD CONSTRAINT fk_file_metadata_processing_job FOREIGN KEY (job_id) REFERENCES public.processing_jobs(id);
    END IF;
EXCEPTION WHEN duplicate_object OR duplicate_table OR invalid_table_definition THEN NULL;
END $$;
-- +goose StatementEnd

